function triangleArea($t){[, $a,$b,$c]=$t;return abs(($b[0]-$a[0])*($c[1]-$a[1])-($b[1]-$a[1])*($c[0]-$a[0]))/2;}
$area=array_sum(array_map('triangleArea',padPenroseTriangles(0,100)));foreach([1,2,3,5,7] as $depth){$tri=padPenroseTriangles($depth,100);verify(count($tri)===padPenroseCount($depth),'Penrose substitution count');verify(abs(array_sum(array_map('triangleArea',$tri))-$area)<1e-7,'Penrose area conserved');}
require PAD.'subs/patterns/_lib/pattern.php';$interlace=include PAD.'subs/patterns/types/interlace.php';[$defs]=$interlace['draw'](['size'=>40,'ink'=>['#335c67','#ae6048'],'bg'=>'#f4eee0','id'=>'weave','w'=>160,'h'=>160]);$doc=new DOMDocument();verify($doc->loadXML('<svg xmlns="http://www.w3.org/2000/svg"><defs>'.$defs.'</defs></svg>'),'interlace SVG');$paths=$doc->getElementsByTagName('path');$crossings=[];for($i=14;$i<$paths->length;$i+=2){$path=$paths->item($i+1);preg_match_all('/-?[0-9]+(?:\.[0-9]+)?/',$path->getAttribute('d'),$coords);$v=array_map('floatval',$coords[0]);$x=(int)round(($v[0]+$v[2])/2);$y=(int)round(($v[1]+$v[3])/2);$crossings["$x,$y"]=$path->getAttribute('stroke');}verify($crossings['0,0']!==$crossings['20,20']&&$crossings['20,20']!==$crossings['40,40'],'positive diagonal alternates');verify($crossings['0,80']!==$crossings['20,60']&&$crossings['20,60']!==$crossings['40,40'],'negative diagonal alternates');verify($crossings['0,0']===$crossings['80,0']&&$crossings['0,0']===$crossings['0,80'],'tile edge parity repeats');
